{
  "root": "root_stack",
  "state": {},
  "elements": {
    "root_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_h1",
        "intro_text",
        "series_heading_h2",
        "narnia_card",
        "earthsea_card",
        "hobbit_card",
        "prydain_card",
        "dark_is_rising_card",
        "context_heading_h2",
        "context_pub_dates",
        "context_completed_series",
        "actions_heading_h2",
        "explore_ya_button",
        "library_search_button"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Classic Fantasy Novels for Young Adults",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Discover a selection of highly acclaimed fantasy series, perfect for young adult readers aged 12-16, with roots stretching back before the year 2000. These foundational tales offer rich worlds, compelling characters, and completed narratives that have captivated generations."
      },
      "children": []
    },
    "series_heading_h2": {
      "type": "Text",
      "props": {
        "text": "Recommended Series Starters",
        "variant": "h2"
      },
      "children": []
    },
    "narnia_card": {
      "type": "Card",
      "props": {},
      "children": [
        "narnia_stack",
        "narnia_summary",
        "narnia_attribute",
        "narnia_button"
      ]
    },
    "narnia_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "narnia_icon",
        "narnia_title_h3"
      ]
    },
    "narnia_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000405_01_1_book.svg"
      },
      "children": []
    },
    "narnia_title_h3": {
      "type": "Text",
      "props": {
        "text": "The Lion, the Witch and the Wardrobe (The Chronicles of Narnia)",
        "variant": "h3"
      },
      "children": []
    },
    "narnia_summary": {
      "type": "Text",
      "props": {
        "text": "Summary: Four siblings discover a magical world through a wardrobe, where they must help the noble lion Aslan defeat the evil White Witch."
      },
      "children": []
    },
    "narnia_attribute": {
      "type": "Text",
      "props": {
        "text": "Key Attribute: An allegorical tale of courage, sacrifice, and the eternal struggle between good and evil, packed with memorable characters and creatures."
      },
      "children": []
    },
    "narnia_button": {
      "type": "Button",
      "props": {
        "label": "Learn More"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.goodreads.com/book/show/100915.The_Lion_the_Witch_and_the_Wardrobe"
          }
        }
      },
      "children": []
    },
    "earthsea_card": {
      "type": "Card",
      "props": {},
      "children": [
        "earthsea_stack",
        "earthsea_summary",
        "earthsea_attribute",
        "earthsea_button"
      ]
    },
    "earthsea_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "earthsea_icon",
        "earthsea_title_h3"
      ]
    },
    "earthsea_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000405_01_1_book.svg"
      },
      "children": []
    },
    "earthsea_title_h3": {
      "type": "Text",
      "props": {
        "text": "A Wizard of Earthsea (Earthsea Cycle)",
        "variant": "h3"
      },
      "children": []
    },
    "earthsea_summary": {
      "type": "Text",
      "props": {
        "text": "Summary: Young Ged, a gifted but proud wizard, unleashes a terrible shadow creature upon the world and must embark on a perilous journey to set things right."
      },
      "children": []
    },
    "earthsea_attribute": {
      "type": "Text",
      "props": {
        "text": "Key Attribute: A deeply philosophical coming-of-age story set in a vast archipelago, exploring themes of balance, responsibility, and self-discovery."
      },
      "children": []
    },
    "earthsea_button": {
      "type": "Button",
      "props": {
        "label": "Learn More"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.goodreads.com/book/show/13642.A_Wizard_of_Earthsea"
          }
        }
      },
      "children": []
    },
    "hobbit_card": {
      "type": "Card",
      "props": {},
      "children": [
        "hobbit_stack",
        "hobbit_summary",
        "hobbit_attribute",
        "hobbit_button"
      ]
    },
    "hobbit_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "hobbit_icon",
        "hobbit_title_h3"
      ]
    },
    "hobbit_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000405_01_1_book.svg"
      },
      "children": []
    },
    "hobbit_title_h3": {
      "type": "Text",
      "props": {
        "text": "The Hobbit",
        "variant": "h3"
      },
      "children": []
    },
    "hobbit_summary": {
      "type": "Text",
      "props": {
        "text": "Summary: Bilbo Baggins, a respectable hobbit, is unexpectedly swept away on an adventure with a company of dwarves and the wizard Gandalf to reclaim a lost treasure from a fearsome dragon."
      },
      "children": []
    },
    "hobbit_attribute": {
      "type": "Text",
      "props": {
        "text": "Key Attribute: A foundational quest narrative that introduced Middle-earth, filled with riddles, trolls, elves, and the beginnings of a much larger world."
      },
      "children": []
    },
    "hobbit_button": {
      "type": "Button",
      "props": {
        "label": "Learn More"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.goodreads.com/book/show/5907.The_Hobbit"
          }
        }
      },
      "children": []
    },
    "prydain_card": {
      "type": "Card",
      "props": {},
      "children": [
        "prydain_stack",
        "prydain_summary",
        "prydain_attribute",
        "prydain_button"
      ]
    },
    "prydain_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "prydain_icon",
        "prydain_title_h3"
      ]
    },
    "prydain_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000405_01_1_book.svg"
      },
      "children": []
    },
    "prydain_title_h3": {
      "type": "Text",
      "props": {
        "text": "The Book of Three (The Prydain Chronicles)",
        "variant": "h3"
      },
      "children": []
    },
    "prydain_summary": {
      "type": "Text",
      "props": {
        "text": "Summary: Taran, an assistant pig-keeper, dreams of heroic deeds and finds himself on an unexpected adventure that will shape the destiny of the magical land of Prydain."
      },
      "children": []
    },
    "prydain_attribute": {
      "type": "Text",
      "props": {
        "text": "Key Attribute: A classic fantasy series inspired by Welsh mythology, following Taran's journey from humble beginnings to a true hero."
      },
      "children": []
    },
    "prydain_button": {
      "type": "Button",
      "props": {
        "label": "Learn More"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.goodreads.com/book/show/24780.The_Book_of_Three"
          }
        }
      },
      "children": []
    },
    "dark_is_rising_card": {
      "type": "Card",
      "props": {},
      "children": [
        "dark_is_rising_stack",
        "dark_is_rising_summary",
        "dark_is_rising_attribute",
        "dark_is_rising_button"
      ]
    },
    "dark_is_rising_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "dark_is_rising_icon",
        "dark_is_rising_title_h3"
      ]
    },
    "dark_is_rising_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000405_01_1_book.svg"
      },
      "children": []
    },
    "dark_is_rising_title_h3": {
      "type": "Text",
      "props": {
        "text": "The Dark Is Rising (The Dark Is Rising Sequence)",
        "variant": "h3"
      },
      "children": []
    },
    "dark_is_rising_summary": {
      "type": "Text",
      "props": {
        "text": "Summary: On his eleventh birthday, Will Stanton discovers he is the last of the Old Ones, an ancient race with powers to fight the rising forces of the Dark."
      },
      "children": []
    },
    "dark_is_rising_attribute": {
      "type": "Text",
      "props": {
        "text": "Key Attribute: A richly atmospheric and suspenseful tale blending Arthurian legend with modern fantasy, steeped in ancient magic and folklore."
      },
      "children": []
    },
    "dark_is_rising_button": {
      "type": "Button",
      "props": {
        "label": "Learn More"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.goodreads.com/book/show/75949.The_Dark_Is_Rising"
          }
        }
      },
      "children": []
    },
    "context_heading_h2": {
      "type": "Text",
      "props": {
        "text": "Selection Context",
        "variant": "h2"
      },
      "children": []
    },
    "context_pub_dates": {
      "type": "Text",
      "props": {
        "text": "Publication Dates: All selected novels were first published before 2000, with the earliest being 1937 and the latest 1973."
      },
      "children": []
    },
    "context_completed_series": {
      "type": "Text",
      "props": {
        "text": "Completed Series: Each book is the first in a completed series, meaning the main story arcs have concluded."
      },
      "children": []
    },
    "actions_heading_h2": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "explore_ya_button": {
      "type": "Button",
      "props": {
        "label": "Explore More YA Fantasy"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.goodreads.com/genres/young-adult-fantasy"
          }
        }
      },
      "children": []
    },
    "library_search_button": {
      "type": "Button",
      "props": {
        "label": "Find Books at Your Library"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.worldcat.org/"
          }
        }
      },
      "children": []
    }
  }
}
